import { KPI } from 'domain/Filter/FilterRules/constants/kpiRules';
import { FilterForm, FilterValue } from 'models/Filters';
import {
  parseCutoffDate,
  shiftYearMonth,
} from 'utils/timePeriod/timePeriodCalendar';

export const BREAKDOWN_DIMENSIONS = [
  'growth_levers',
  'beer_price_segment',
  'pack_type',
  'portfolios',
  'global_brands',
  'brands',
  'sub_brands',
] as const;

const getLastCompleteQuarterStart = (date: FilterValue) => {
  const parsed = parseCutoffDate(typeof date === 'string' ? date : undefined);
  if (!parsed) {
    return new Date(Number.NaN);
  }

  const currentQuarter = Math.floor(parsed.month / 3);
  const targetQuarter = currentQuarter === 0 ? 3 : currentQuarter - 1;
  const targetYear = currentQuarter === 0 ? parsed.year - 1 : parsed.year;

  return new Date(targetYear, targetQuarter * 3, 1);
};

const getPreviousThreeMonthsStart = (dtEnd: FilterValue) => {
  const parsed = parseCutoffDate(typeof dtEnd === 'string' ? dtEnd : undefined);
  if (!parsed) {
    return new Date(Number.NaN);
  }

  const start = shiftYearMonth(parsed.year, parsed.month, -2);
  return new Date(start.year, start.month - 1, 1);
};

const hasValue = (value: FilterValue) =>
  value != null && value !== '' && value !== 'All';

export const hasBreakdownDimensionsApplied = (applied: FilterForm) =>
  BREAKDOWN_DIMENSIONS.some((dimension) => hasValue(applied[dimension]));

export const isMarketShareKpi = (kpi: FilterValue) =>
  kpi === KPI.MARKET_SHARE || kpi === KPI.MARKET_SHARE_OFFICIAL;

export const buildPeriodSignature = (applied: FilterForm) =>
  [applied.kpis, applied.period_type, applied.periods, applied.dt_end].join(
    '|',
  );

export const isInvalidMarketShareTimePeriod = (
  applied: FilterForm,
  lastDataRefresh: Date | null | undefined,
) => {
  const periodTypes = [applied.period_type, applied.periods].filter(
    (period): period is string => typeof period === 'string' && period !== '',
  );

  if (!lastDataRefresh) {
    return periodTypes.includes('MTH');
  }

  const lastCompleteQuarterStart = getLastCompleteQuarterStart(applied.dt_end);
  const previousThreeMonthsStart = getPreviousThreeMonthsStart(applied.dt_end);
  const appliedMonth = new Date(applied.dt_end as string);

  return periodTypes.some(
    (periodType) =>
      (periodType === 'QTR' && lastDataRefresh < lastCompleteQuarterStart) ||
      (periodType === 'R3M' && lastDataRefresh < previousThreeMonthsStart) ||
      (periodType === 'MTH' && lastDataRefresh < appliedMonth),
  );
};

export const buildRestoreFilters = (
  applied: FilterForm,
  pageDefaults: Partial<FilterForm>,
  lastValidFilters: FilterForm | null,
) =>
  lastValidFilters ?? {
    ...applied,
    periods: pageDefaults.periods ?? applied.periods,
    period_type: pageDefaults.period_type ?? applied.period_type,
    dt_end: pageDefaults.dt_end ?? applied.dt_end,
  };
